bool load_key_file(const std::string& key_file_path, std::string& key) {
  std::ifstream file(key_file_path);
  if (!file.is_open()) {
    return false;
  }
  std::string line;
  while (std::getline(file, line)) {
    key += line;
  }
  return verify_key(key, master_key);
}

