  // Log the result
  logResult(testCase, passed);
  // End the User Acceptance Testing process
  endUAT();
}

void logResult(std::string testCase, bool passed) {
  std::ofstream logFile("test_results.log", std::ios::app);
  if (logFile.is_open()) {
