  for (const auto& feedback : feedback) {
    if (!validate_client_details(feedback.client_details)) {
      return false;
    }
    if (!validate_syndromes(feedback.syndromes)) {
      return false;
    }
    if (!validate_lab_test(feedback.lab_test)) {
      return false;
    }
    if (!validate_drugs(feedback.drugs)) {
      return false;
    }
    feedback.valid = true;
  }
  return true;
}

